import "core-js/modules/es.array.push.js";
/* eslint-disable */

import { format_Date } from "@/JsonFiles/DateFormate.js";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { list_billing_transactions, genrate_billing_invoice } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import ViewBillingInfo from "./ViewBillingInfo.vue";
import SnackBar from "@/components/SnackBar.vue";
const FileSaver = require("file-saver");
import axios from "axios";
export default {
  mixins: [get_Org_details],
  components: {
    ViewBillingInfo,
    SnackBar
  },
  data() {
    return {
      tableData: [],
      SnackBarComponent: {},
      tableLoading: false,
      fixed: true,
      createdOn: "",
      billingRate: "",
      billingcurrency: "",
      headers: [{
        title: "Billing Id",
        value: "billing_id",
        sortable: false
      }, {
        title: "Amount",
        value: "total_ammount_to_pay",
        sortable: false
      }, {
        title: "Month",
        value: "billing_month",
        sortable: false
      }, {
        title: "Year",
        value: "billing_year",
        sortable: false
      }, {
        title: "Status",
        value: "billing_due",
        sortable: false
      }, {
        title: "Actions",
        value: "action",
        sortable: false
      }],
      rowInfo: {},
      componentCheck: 0,
      ViewbillingDialog: false,
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0
    };
  },
  async created() {
    this.windowHeight = window.innerHeight - 200;
    await this.get_billing_details();
    await this.get_Org_details();
    this.get_details();
  },
  computed: {
    totalCount() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    async download_invoice(item) {
      try {
        let result = await API.graphql(graphqlOperation(genrate_billing_invoice, {
          input: {
            transaction_id: item.transaction_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.genrate_billing_invoice);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.dwonload_pdf(response.url, item.billing_month + "-" + item.billing_year);
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async dwonload_pdf(url, fileName) {
      axios({
        url: url,
        method: "GET",
        responseType: "blob" // Set the response type to blob
      }).then(response => {
        // Create a blob from the response
        const blob = new Blob([response.data], {
          type: response.headers["content-type"]
        });

        // Use the FileSaver library to save the file
        FileSaver.saveAs(blob, fileName);
      }).catch(error => {
        console.error("Error downloading the file:", error);
      });
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    handle_row_click(value) {
      this.rowInfo = value;
      this.ViewbillingDialog = true;
      this.componentCheck = 1;
    },
    async get_billing_details() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_billing_transactions, {
          organization_id: data.organization.organization_id,
          billing_due: "ALL",
          limit: 200,
          next_token: null
        }));
        this.tableLoading = false;
        this.tableData = [];
        var dataArray = [];
        var response = JSON.parse(result.data.list_billing_transactions);
        this.tableData = response.details;
        this.$store.commit("SetadministrationCheck", true);
        this.updatePageItems();
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    back_action() {
      this.$emit("backAction", 0);
    },
    get_details() {
      this.createdOn = this.orgDetails.organization.organization_created_on;
      this.billingRate = this.orgDetails.organization.billing_rate;
      this.billingcurrency = this.orgDetails.organization.billing_currency == "DOLLAR" ? "$" : " " + this.orgDetails.organization.billing_currency;
    },
    fetch_value(val) {
      return format_Date(val);
      // const d = new Date(parseInt(val * 1000));
      // var date = d.getDate().toLocaleString();
      // var month = (d.getMonth() + 1).toLocaleString();
      // var year = d.getFullYear();

      // return (
      //   (+date <= 9 ? "0" + date : date) +
      //   "/" +
      //   (+month <= 9 ? "0" + month : month) +
      //   "/" +
      //   year
      // );
    },
    updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      this.paginatedItems = this.tableData.slice(start, end);
    }
  }
};
